INSERT OR REPLACE INTO "SiteContent" ("id","section","data","updatedAt") VALUES ('content_services','services','[{"icon":"Bot","title":"Agentic AI & Voice Pipelines","description":"Design and deploy autonomous AI agents, Vapi-based real-time voice assistants, and multi-tool orchestration workflows integrating OpenAI models and Amazon Bedrock.","accent":"#E8536A"},{"icon":"Workflow","title":"LLM & RAG Architecture","description":"Build high-precision RAG systems using LangChain, LLaMA 3, DeepSeek R1, and FAISS vector databases for semantic document search, healthcare triage, and domain chatbots.","accent":"#D4A853"},{"icon":"Code","title":"Full-Stack Python & Django","description":"Architect scalable web applications and REST APIs with Django, Flask, and FastAPI backends, paired with modern TypeScript/React frontends and robust database models.","accent":"#1B2A4A"},{"icon":"Cpu","title":"Web & Workflow Automation","description":"Develop end-to-end browser automation scripts with Playwright, desktop robotic automation with UiPath, and manage cloud deployments on Ubuntu Linux and AWS EC2.","accent":"#FF7B8A"}]',CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO "SiteContent" ("id","section","data","updatedAt") VALUES ('content_process','process','[{"step":1,"title":"Problem Scoping","description":"Analyze the core requirements, constraints, and data sources.","icon":"Search"},{"step":2,"title":"System & Model Design","description":"Select optimal models, vector indexes, and API architectures.","icon":"PenTool"},{"step":3,"title":"Pipeline Engineering","description":"Write clean Python/Django code, connect LLM tools, and wire integrations.","icon":"Hammer"},{"step":4,"title":"Testing & Evaluation","description":"Benchmark RAG accuracy, test edge cases, and validate with Playwright.","icon":"ShieldCheck"},{"step":5,"title":"Cloud Deployment","description":"Deploy to AWS EC2 / Ubuntu servers with secure env configs and CI/CD.","icon":"Rocket"},{"step":6,"title":"Monitoring & Tuning","description":"Analyze latency, optimize token costs, and fine-tune response quality.","icon":"RefreshCw"}]',CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO "SiteContent" ("id","section","data","updatedAt") VALUES ('content_why_us','why_us','[{"icon":"Bot","title":"Specialized in Agentic AI","description":"Hands-on experience deploying live voice agents, multi-agent frameworks, and real-time LLM systems in production."},{"icon":"Code","title":"Solid Python Foundation","description":"Deep expertise in Django, Django ORM, Flask, FastAPI, and data structures from BS Software Engineering at COMSATS."},{"icon":"Cpu","title":"End-to-End Automation","description":"Proven track record automating complex web workflows with Playwright and desktop procedures with UiPath on AWS."},{"icon":"ShieldCheck","title":"Production Mindset","description":"Security-first API design, Linux server administration, and reliable testing for mission-critical software."}]',CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO "SiteContent" ("id","section","data","updatedAt") VALUES ('content_testimonials','testimonials','[{"quote":"Sohaib developed real-time voice agents and automated Playwright pipelines that significantly accelerated our engineering workflows. Outstanding grasp of modern AI.","name":"Engineering Lead","role":"Octathorn Technologies","rating":5},{"quote":"His final year project AgriConnect combined a complex Django marketplace with deep learning crop disease detection seamlessly. Diligent, resourceful, and technically sound.","name":"Project Supervisor","role":"COMSATS University","rating":5},{"quote":"Quickly integrated RAG pipelines and Hugging Face NLP models during his internship. An engineer who genuinely loves solving difficult software problems.","name":"Technical Mentor","role":"Eziline Software House","rating":5}]',CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO "SiteContent" ("id","section","data","updatedAt") VALUES ('content_faqs','faqs','[{"question":"What are your core technical specializations?","answer":"My primary expertise is in Agentic AI, Generative AI, and Backend Engineering. I work extensively with Python, Django, LangChain, OpenAI, Vapi (voice AI), Playwright automation, and AWS cloud environments."},{"question":"What is your educational background?","answer":"I hold a 16-year BS in Software Engineering from COMSATS University Wah Cantt (March 2025, CGPA 3.21), with coursework focused on Artificial Intelligence, Machine Learning, Data Mining, and Algorithms."},{"question":"What projects have you engineered?","answer":"Key projects include AgriConnect (a digital farm marketplace with deep learning disease detection), Smart AI Doctor (medical consultation chatbot with DeepSeek R1 & voice synthesis), and Smart Islamic Guider (RAG-based QA with LLaMA 3)."},{"question":"Are you available for contract or full-time roles?","answer":"Yes, I am open to innovative AI engineering roles, high-impact consulting, and agentic AI development opportunities. You can reach out directly via email or LinkedIn."}]',CURRENT_TIMESTAMP);
