INSERT OR REPLACE INTO "SiteContent" ("id","section","data","updatedAt") VALUES ('content_about_story','about_story','{"paragraphs":["I am a Software Engineer and AI Engineer based in Islamabad, Pakistan, with a strong foundation in Python, Django, and modern AI architectures. Passionate about AI-driven development, backend engineering, and building scalable systems, I turn complex machine learning models into reliable, user-friendly digital products.","Currently at Octathorn Technologies as an AI Automation Engineer, I design and deploy agentic AI systems, real-time voice agents using Vapi frameworks, and automated decision-making pipelines that coordinate multiple AI agents, APIs, and business platforms.","I graduated with a BS in Software Engineering from COMSATS University Wah Cantt (CGPA 3.21). My portfolio features production systems including AgriConnect (digital farm marketplace with deep learning crop disease screening), Smart AI Doctor (DeepSeek R1 medical chatbot with voice synthesis), and Smart Islamic Guider (RAG over Quran and Hadith)."]}',CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO "SiteContent" ("id","section","data","updatedAt") VALUES ('content_about_milestones','about_milestones','[{"year":"Feb 2026 – Present","title":"AI Automation Engineer — Octathorn Technologies Private Limited","description":"Design and deploy agentic AI systems, real-time voice agents with Vapi & OpenAI, multi-agent decision pipelines, enterprise Claude MCP integrations, and UiPath/n8n automation.","icon":"Bot","accent":"#E8536A"},{"year":"Sep 2025 – Jan 2026","title":"Automation Engineer Intern — Octathorn Technologies","description":"Developed web automation test suites using Playwright, managed Ubuntu Linux environments, and automated desktop workflows using UiPath via RDP on AWS.","icon":"Cpu","accent":"#D4A853"},{"year":"Jan 2025 – Apr 2025","title":"Python Developer Intern — Eziline Software House","description":"Built intelligent web apps and LLM chatbots with Python, Django, LangChain, and LLaMA 3. Deployed RAG pipelines, Hugging Face NLP models, and disease detection classifiers.","icon":"Code","accent":"#1B2A4A"},{"year":"March 2025","title":"BS Software Engineering — COMSATS University","description":"Graduated with CGPA 3.21. Majors in Artificial Intelligence, Machine Learning, Data Mining, and Data Structures & Algorithms.","icon":"Award","accent":"#10B981"},{"year":"Dec 2024","title":"AgriConnect (Final Year Project)","description":"Engineered a digital agriculture marketplace with deep learning crop disease screening and Django backend for small-scale farmers.","icon":"Package","accent":"#E8536A"}]',CURRENT_TIMESTAMP);
COMMIT;
